async function prepareGroups(groups) { const result = new Array(groups.length); let next = 0; const worker = async () => { while (next < groups.length && await waitIfPaused()) { const index = next++; const group = groups[index]; run.value.current = `正在读取来源包 ${index + 1}/${groups.length}`; try { result[index] = { group, evidence: await treeEvidence(group), target: await currentTargetAudit(group) } } catch { result[index] = { group, evidence: { ok: false, reason: '读取这个来源包时出现异常；没有进行任何文件操作。' }, target: { issues: [] } } } finally { run.value.completed += 1 } } }; await Promise.all(Array.from({ length: Math.min(workers, groups.length) }, worker)); return result.filter(Boolean) }
async function inspect() {
  if (!canUseApi.value || loading.value) { notice.value = '当前 MoviePilot 没有注入认证 API，无法安全检查。'; return }
  loading.value = true; cards.value = []; selected.value = null; preview.value = null; scope.value = emptyScope(); control.value = { paused: false, stopped: false }
  run.value = { ...emptyRun(), phase: '正在读取当前整理历史', startedAt: Date.now() }; clock = window.setInterval(() => { run.value = { ...run.value } }, 1000)
  try {
    const [failed, successful, events, _sources] = await Promise.all([historyRows(false, '失败整理历史'), historyRows(true, '成功整理历史'), eventIndex(), readSources()])
    scope.value.failure = failed.length
    const { activeFailed, eventSuccess, recovered } = reviewHistoryScope({ failed, successful, events })
    const groups = [...groupsFor([...eventSuccess, ...activeFailed]).values()]
    scope.value.recovered = recovered; scope.value.currentFailures = activeFailed.length; scope.value.eventSuccess = eventSuccess.length; scope.value.inventoryPackages = groups.length
    run.value.total = groups.length; run.value.phase = `范围已建立：${groups.length} 个当前整理来源包；正在读取必要证据`
    const prepared = await prepareGroups(groups), coverage = auditCoverage({ expected: groups.length, scanned: prepared.length, limited: control.value.stopped || Boolean(scope.value.unavailable.length) })
    scope.value.inventoryState = `${coverage.message}；本轮只检查未恢复失败 ${activeFailed.length} 条和插件启用后记录的成功整理 ${eventSuccess.length} 条，不扫描整个媒体库，也不把历史失败次数当作问题数。`
    const modelQueue = prepared.filter(item => needsModelReview(item.group, item.evidence, item.target))
    const baseline = prepared.filter(item => !needsModelReview(item.group, item.evidence, item.target)).map(item => baselineCard(item.group, item.evidence, item.target))
    baseline.forEach(card => addStat(card))
    cards.value = baseline.filter(card => card.state !== 'clear')
    run.value.resultCompleted = baseline.length
    run.value.phase = `规则筛选完成：${baseline.length} 个无需 AI，${modelQueue.length} 个可疑包进入模型队列`
    const diagnoses = await diagnoseBundles(modelQueue), queue = [...modelQueue]
    const worker = async () => { while (queue.length && await waitIfPaused()) { const item = queue.shift(); if (!item) return; run.value.current = `正在核验可疑包 ${run.value.resultCompleted + 1}/${prepared.length}`; let card; try { card = await inspectGroup(item.group, item.evidence, item.target, diagnoses.get(item.group.key) || { error: control.value.stopped ? '检查已停止' : '模型没有返回这个包的结构化判断。' }) } catch { card = { ...item.group, state: 'unavailable', reason: '核验这个包时出现异常；没有进行任何文件操作。' } } if (card.state !== 'clear') cards.value = [...cards.value, card]; run.value.resultCompleted += 1; addStat(card) } }
    await Promise.all(Array.from({ length: Math.min(workers, modelQueue.length) }, worker)); scope.value.verificationQueue = cards.value.length; run.value.finishedAt = Date.now()
    if (control.value.stopped) notice.value = `已停止：已读取 ${run.value.completed}/${run.value.total} 个来源包，已产出 ${run.value.resultCompleted} 个结果；全程零写入。`
    else { run.value.phase = '检查完成'; notice.value = `${coverage.complete ? '完整覆盖已完成' : '检查未覆盖完整范围'}：${run.value.resultCompleted} 个来源包中 ${scope.value.fastClear} 个无需 AI，${cards.value.length} 个需要查看；全程零写入。` }
  } catch (error) { run.value.phase = '检查未完成'; notice.value = error?.message || '无法建立当前媒体库存；没有改动文件。' }
  finally { loading.value = false; if (clock) window.clearInterval(clock); clock = null }
}
function open(card, next = 'identity') { selected.value = card; preview.value = null; tab.value = next }
function choose(candidate) { selected.value = { ...selected.value, state: 'confirmed', identity: candidate, userConfirmed: true, reason: '已由你确认作品；下一步只能生成官方零写入预览。' }; cards.value = cards.value.map(card => card.key === selected.value.key ? selected.value : card) }
function previewPayload(item, target = {}) { return { fileitem: item.source, logid: item.historyIds?.[0], transfer_type: target.transfer_type || 'link', target_storage: target.target_storage, target_path: target.target_path, scrape: target.scrape, library_type_folder: target.library_type_folder, library_category_folder: target.library_category_folder, preview: true, reorganize: false, media_source: item.identity.media_source, media_id: item.identity.media_id, type_name: item.identity.type_name, season: item.identity.season } }
function previewIssues(result, target) { const items = result?.items || [], summary = result?.summary || {}, issues = []; if (!target?.target_path || !target?.transfer_type) issues.push('当前目录规则没有给出唯一完整目标'); if (!items.length && !summary.total) issues.push('官方没有返回逐文件预览'); if (summary.failed || items.some(item => item?.success === false || !item?.target)) issues.push('官方预览存在失败或缺失目标'); const episodes = items.map(item => Number(item?.episode)).filter(Number.isFinite); if (new Set(episodes).size !== episodes.length) issues.push('官方预览包含重复集号'); return issues }
async function auditOrganization() { if (!selected.value?.identity || selected.value.state !== 'confirmed') return; loading.value = true; preview.value = null; try { const base = previewPayload(selected.value), [historyRaw, targetRaw] = await Promise.all([props.api.post('transfer/manual/history', base, { feedback: 'silent' }), props.api.post('transfer/manual/target-path', base, { feedback: 'silent' })]), history = dataOf(historyRaw), target = dataOf(targetRaw); if (history?.success === false || target?.success === false) throw new Error(history?.message || target?.message || '官方整理审计被拒绝'); const historyData = history?.data ?? history, targetData = target?.data ?? target, raw = dataOf(await props.api.post('transfer/manual', previewPayload(selected.value, targetData), { feedback: 'silent' })); if (raw?.success === false) throw new Error(raw.message || '官方预览被拒绝'); const data = raw?.data ?? raw; preview.value = { history: historyData || {}, target: targetData || {}, data: data || {}, issues: previewIssues(data, targetData), fingerprint: selected.value.evidence?.fingerprint }; notice.value = preview.value.issues.length ? '已生成官方逐文件预览，但发现冲突，不能进入写入。' : '官方逐文件预览完成。旧硬链接清理仍锁定：官方预览没有逐项删除清单。' } catch (error) { notice.value = error?.message || '官方预览失败；没有改动文件。' } finally { loading.value = false } }
async function repairOrganization() { if (!selected.value?.identity || !preview.value || preview.value.issues.length) return; if (!window.confirm('确认按刚刚的官方预览处理吗？MoviePilot 会先清除这条成功历史对应的旧媒体库硬链接，再从下载原文件重建；不会删除下载原文件。')) return; loading.value = true; try { const raw = dataOf(await props.api.post('transfer/manual', { ...previewPayload(selected.value, preview.value.target), preview: false, reorganize: false }, { feedback: 'silent' })); if (raw?.success === false) throw new Error(raw.message || '官方重建被拒绝'); preview.value = { ...preview.value, receipt: raw?.data ?? raw }; notice.value = 'MoviePilot 已接管这次受控重建；请以它返回的整理结果为准。' } catch (error) { notice.value = error?.message || '官方重建失败；请重新生成预览后再试。' } finally { loading.value = false } }
</script>

<template>
  <main class="governor-page">
    <header class="hero"><div><p class="eyebrow">MediaGovernor 2.1</p><h1>媒体治理工作台</h1><p>只检查尚未恢复的失败整理，以及插件启用后新发生的整理；不再把全库或旧历史当作待检查包。</p></div><div class="actions"><button class="primary" :disabled="loading" @click="inspect">{{ loading ? '检查进行中…' : hasRun ? '重新检查' : '开始检查' }}</button><button v-if="loading && !control.paused" class="secondary" @click="pause">暂停</button><button v-if="loading && control.paused" class="secondary" @click="resume">继续</button><button v-if="loading" class="danger" @click="stop">停止</button></div></header>
    <section class="progress" aria-live="polite"><div class="progress-head"><strong>{{ run.phase }}</strong><span>已读 {{ run.completed }}/{{ run.total }} · AI {{ run.aiCompleted }}/{{ run.aiTotal }} · 已产出 {{ run.resultCompleted }} · {{ elapsed }}</span></div><div class="track"><i :style="{ width: `${progress}%` }" /></div><p v-if="run.current">{{ run.current }}。停止会阻止后续读取和模型批次；已完成结果保留。</p><div class="stats"><span>规则通过 <b>{{ run.stats.clear }}</b></span><span>已确认 <b>{{ run.stats.confirmed }}</b></span><span>待确认 <b>{{ run.stats.selection }}</b></span><span>资料不足 <b>{{ run.stats.insufficient }}</b></span><span>不可读取 <b>{{ run.stats.unavailable }}</b></span></div></section>
    <section class="scope"><h2>这次到底查了什么</h2><div class="scope-grid"><span>当前来源包 <b>{{ scope.inventoryPackages }}</b></span><span>规则通过 <b>{{ scope.fastClear }}</b></span><span>需要查看 <b>{{ scope.verificationQueue }}</b></span><span>未恢复失败 <b>{{ scope.currentFailures }}</b></span><span>新成功整理 <b>{{ scope.eventSuccess }}</b></span></div><p>失败历史只是线索，不是问题总数。安装 2.1 后会记录新的成功/失败整理；成功记录也会做整包核验，专门抓“表面成功但分错”的情况。不会递归扫描整个媒体库。{{ scope.inventoryState }}</p><p v-if="scope.unavailable.length" class="reason">{{ scope.unavailable.join('；') }}</p></section>
    <p v-if="notice" class="notice" role="status">{{ notice }}</p><nav class="tabs"><button :class="{ active: tab === 'identity' }" @click="tab = 'identity'">1. 找对作品</button><button :class="{ active: tab === 'organize' }" @click="tab = 'organize'">2. 整理正确</button><button :class="{ active: tab === 'fixtures' }" @click="tab = 'fixtures'">3. 验收样例</button></nav>
    <section v-if="tab === 'identity'" class="panel"><div class="section-head"><div><h2>找对作品</h2><p>这里显示身份、当前硬链接目标或历史记录存在冲突的包。模型负责按完整包证据交叉核验；不确定就保留给你确认。</p></div><span class="chip">可用影视源 {{ sources.filter(videoSource).length }}</span></div><details v-if="sources.length" class="source-status"><summary>查看数据源查询状态</summary><p v-for="source in sources" :key="source.id || source.label">{{ source.label }}：{{ source.state }}{{ source.hits ? `（返回 ${source.hits} 条）` : '' }}</p></details><p v-if="!cards.length" class="empty">{{ hasRun ? '完整覆盖内没有发现需要查看的包。' : '尚未读取。开始后只显示真正需要处理的包。' }}</p><article v-for="card in cards" :key="card.key" class="card" :class="card.state"><div><span class="state">{{ card.state === 'confirmed' ? '作品已确认，待官方预览核验' : card.state === 'needs_selection' ? '问题已确认，待选择作品' : card.state === 'insufficient' ? '问题已确认，资料不足' : card.state === 'non_media' ? '样片或测试残留' : '来源不可读取、目标已变动或当前失败残留' }}</span><h3>{{ card.identity?.title || (card.state === 'non_media' ? '不是待整理正片' : '还没有可靠作品身份') }}{{ card.identity?.year ? `（${card.identity.year}）` : '' }}</h3><p v-if="card.evidence">{{ evidenceText(card.evidence) }}；已读 {{ card.evidence.directories }} 个目录节点、{{ card.evidence.entries.length }} 项名称证据。</p><p>{{ card.reason }}</p></div><button class="secondary" @click="open(card)">查看完整依据与候选</button></article></section>
    <section v-else-if="tab === 'organize'" class="panel"><div class="section-head"><div><h2>整理正确</h2><p>这里核对已经发现的当前问题包。确认作品后生成 MoviePilot 官方逐文件预览，再由你确认是否执行受控重建。</p></div><span class="chip">只读对账</span></div><p v-if="!organizationCards.length" class="empty">本轮没有需要整理核验的问题包。</p><article v-for="card in organizationCards" :key="card.key" class="card" :class="{ confirmed: card.identity, needs_selection: !card.identity }"><div><span class="state">{{ card.identity ? '正在核对当前整理结构' : '身份未确认，整理核验锁定' }}</span><h3>{{ card.identity?.title || '尚无可靠作品身份' }}{{ card.identity?.year ? `（${card.identity.year}）` : '' }}</h3><p v-if="card.evidence">{{ evidenceText(card.evidence) }}。{{ organizationIssues(card).length ? organizationIssues(card).join('；') : '尚未发现可由当前只读证据证明的额外冲突；仍可生成官方预览。' }}</p><p v-else>{{ card.reason }}</p></div><button v-if="card.state === 'confirmed'" class="primary" @click="open(card, 'organize'); auditOrganization()">生成官方逐文件预览</button><button v-else class="secondary" @click="open(card, 'identity')">先核对作品身份</button></article></section>
    <section v-else class="panel"><div class="section-head"><div><h2>验收样例</h2><p>这些是脱敏固定样例。它们调用与实际检查相同的分包、候选确认和整理审计规则，不读取 NAS，也不调用模型。</p></div><span class="chip">{{ fixtures.filter(item => item.pass).length }}/{{ fixtures.length }} 通过</span></div><article v-for="fixture in fixtures" :key="fixture.id" class="card" :class="fixture.pass ? 'confirmed' : 'insufficient'"><div><span class="state">{{ fixture.pass ? '通过' : '失败' }}</span><h3>{{ fixture.label }}</h3><p>正确答案：{{ fixture.expected }}；实际结果：{{ fixture.actual }}</p></div><p>{{ fixture.pass ? '规则结果与预期一致。' : '规则结果与预期不一致；本版本不能进入候选安装。' }}</p></article></section>
    <div v-if="selected" class="backdrop" @click.self="selected = null"><section class="modal"><button class="close" aria-label="关闭" @click="selected = null">×</button><template v-if="tab === 'identity'"><p class="eyebrow">完整证据账本</p><h2>{{ selected.identity?.title || '候选核验' }}</h2><p v-if="selected.evidence">{{ evidenceText(selected.evidence) }}。已读取 {{ selected.evidence.entries.length }} 个目录项，证据指纹 {{ selected.evidence.fingerprint }}。</p><p>{{ selected.reason }}</p><section v-if="selected.diagnosis" class="diagnosis"><strong>整包模型判断</strong><p>{{ diagnosisText(selected.diagnosis) }}</p><p v-if="selected.diagnosis.reasons?.length">理由：{{ selected.diagnosis.reasons.join('；') }}</p><p v-if="selected.diagnosis.expected_episodes?.length">模型预期集号：{{ selected.diagnosis.expected_episodes.join('、') }}</p><p v-if="selected.diagnosis.evidence_indexes?.length">支持它的目录项编号：{{ selected.diagnosis.evidence_indexes.map(index => index + 1).join('、') }}</p></section><details v-if="selected.evidence"><summary>查看名称线索（{{ selected.evidence.queries.length }} 条）</summary><p>{{ selected.evidence.queries.join('；') || '没有可用线索' }}</p></details><details v-if="selected.evidence"><summary>查看发送给模型的目录结构（{{ selected.evidence.entries.length }} 项）</summary><ul><li v-for="(entry, index) in selected.evidence.entries" :key="`${entry.name}-${index}`">{{ '　'.repeat(entry.depth || 0) }}{{ entry.type === 'dir' ? '📁' : '📄' }} {{ entry.name }}</li></ul></details><div v-if="selected.candidates?.length" class="candidate-list"><article v-for="candidate in selected.candidates" :key="candidateKey(candidate)" class="candidate" :class="{ conflicted: candidate.conflicts?.length }"><div><strong>{{ candidate.title }}{{ candidate.year ? `（${candidate.year}）` : '' }}</strong><p>{{ candidate.original_title ? `原名：${candidate.original_title}` : '原名：未返回' }}{{ candidate.en_title ? `；英文：${candidate.en_title}` : '' }}</p><p class="candidate-meta">{{ candidateMeta(candidate) }}</p><p>检索线索：{{ candidate.queries?.join('；') || '原生文件识别' }}。支持：{{ candidate.reasons?.join('；') || '只有官方搜索命中' }}</p><p v-if="candidate.conflicts?.length" class="reason">冲突：{{ candidate.conflicts.join('；') }}</p></div><button class="secondary" @click="choose(candidate)">确认是这部</button></article></div><p v-else class="empty">MoviePilot 没有返回候选；这不代表文件为空。</p></template><template v-else><p class="eyebrow">官方逐文件预览</p><h2>{{ selected.identity?.title }}</h2><button class="primary" :disabled="loading" @click="auditOrganization">{{ loading ? '正在生成…' : '重新生成预览' }}</button><section v-if="preview" class="audit"><div class="audit-grid"><span>命中旧成功记录 <b>{{ preview.history?.history_count || 0 }}</b></span><span>预览文件 <b>{{ preview.data?.summary?.total || preview.data?.items?.length || 0 }}</b></span><span>可创建 <b>{{ preview.data?.summary?.success || 0 }}</b></span><span>预览失败 <b>{{ preview.data?.summary?.failed || 0 }}</b></span></div><p v-if="preview.issues.length" class="reason">已锁定：{{ preview.issues.join('；') }}</p><p v-else class="safe">新硬链接预览完整。确认后只调用 MoviePilot 官方整理：它只会清理这条成功历史对应的旧媒体库硬链接，再从原始下载文件重建；不会删除下载原文件。</p><button v-if="!preview.receipt" class="primary" :disabled="loading" @click="repairOrganization">确认按此预览重建</button><p v-else class="safe">本次已交给 MoviePilot 执行；请重新检查确认结果。</p><details><summary>查看官方逐文件计划（{{ preview.data?.items?.length || 0 }} 项）</summary><ul><li v-for="(item, index) in preview.data?.items || []" :key="index">{{ item?.title || selected.identity?.title }} · {{ item?.episode ? `第 ${item.episode} 集` : '影片/未标集' }} · {{ item?.target ? '目标已生成' : '没有目标' }}</li></ul></details></section></template></section></div>
  </main>
</template>

